// (1)
fun compare(a: MerkleTree, b: MerkleTree): MerkleDiff {
    val found = ArrayList<Int>()
    var n = 0
    fun visit(node: Int) {
        n++
        if (a.nodes[node].contentEquals(b.nodes[node])) return
        if (node >= a.leaves) { found += node - a.leaves; return }
        visit(2 * node); visit(2 * node + 1)
    }
    visit(1)
    return MerkleDiff(found, n)
}
